import zipfile
from xml.etree import ElementTree as ET

M = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
NS = {"m": M}

with zipfile.ZipFile("budget.xlsx") as z:
    names = z.namelist()
    sheet_xml = z.read("xl/worksheets/sheet1.xml")
    shared_xml = z.read("xl/sharedStrings.xml") if "xl/sharedStrings.xml" in names else None

ss = []
if shared_xml is not None:
    sroot = ET.fromstring(shared_xml)
    for si in sroot.findall("m:si", NS):
        ss.append("".join(t.text or "" for t in si.iter(M + "t")))

root = ET.fromstring(sheet_xml)
grid = {}
for row in root.iter(M + "row"):
    r = int(row.get("r"))
    for c in row.findall("m:c", NS):
        ref = c.get("r")
        t = c.get("t")
        v = c.find("m:v", NS)
        isel = c.find("m:is", NS)
        if t == "inlineStr" and isel is not None:
            val = "".join(tn.text or "" for tn in isel.iter(M + "t"))
        elif t == "s" and v is not None:
            val = ss[int(v.text)]
        elif v is not None:
            val = v.text
        else:
            val = None
        grid[ref] = val

# build a rectangular printout
import re
cols = {}
for ref in grid:
    m = re.match(r"([A-Z]+)(\d+)", ref)
    if m:
        cols.setdefault(int(m.group(2)), []).append((m.group(1), grid[ref]))

for r in sorted(cols):
    cells = cols[r]
    cells.sort(key=lambda x: x[0])
    print(f"row {r}: " + " | ".join(f"{a}={b}" for a, b in cells))

import zipfile
import re
from xml.etree import ElementTree as ET

def local(tag):
    return tag.rsplit("}", 1)[-1]

with zipfile.ZipFile("budget.xlsx") as z:
    sheet_xml = z.read("xl/worksheets/sheet1.xml")
    try:
        shared_xml = z.read("xl/sharedStrings.xml")
    except KeyError:
        shared_xml = None

ss = []
if shared_xml is not None:
    sroot = ET.fromstring(shared_xml)
    for si in sroot.iter():
        if local(si.tag) == "si":
            ss.append("".join(t.text or "" for t in si.iter() if local(t.tag) == "t"))

root = ET.fromstring(sheet_xml)
print("sheet root local tag:", local(root.tag))

grid = {}
for row in root.iter():
    if local(row.tag) != "row":
        continue
    for c in row:
        if local(c.tag) != "c":
            continue
        ref = c.get("r")
        t = c.get("t")
        v = c.find("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}v")
        isel = c.find("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}is")
        if t == "inlineStr" and isel is not None:
            val = "".join(tn.text or "" for tn in isel.iter() if local(tn.tag) == "t")
        elif t == "s" and v is not None:
            val = ss[int(v.text)]
        elif v is not None:
            val = v.text
        else:
            val = ""
        grid[ref] = val

rows = {}
for ref, val in grid.items():
    m = re.match(r"([A-Z]+)(\d+)", ref)
    if m:
        rows.setdefault(int(m.group(2)), []).append((m.group(1), val))

for r in sorted(rows):
    cells = sorted(rows[r], key=lambda x: x[0])
    print("row %d: %s" % (r, " | ".join("%s=%s" % (a, b) for a, b in cells)))

nums = []
for v in grid.values():
    try:
        nums.append(float(v))
    except (TypeError, ValueError):
        pass
print("TOTAL of all numeric cells:", sum(nums))

